extends SceneTree
@warning_ignore_start("untyped_declaration", "inference_on_variant", "unsafe_property_access", "unsafe_method_access", "unsafe_cast", "unsafe_call_argument", "return_value_discarded", "narrowing_conversion", "int_as_enum_without_cast")

# Debug mode flag
var debug_mode = false

# get_scene_tree: marker placed inside a children array when a subtree is cut
# off at the depth boundary. Markers consume the same output budget as real nodes.
const GET_SCENE_TREE_MARKER := "__truncated__"
const GET_SCENE_TREE_DEFAULT_MAX_DEPTH := 32
const GET_SCENE_TREE_DEFAULT_MAX_NODES := 1000

func _init():
    var args = OS.get_cmdline_args()

    # Check for debug flag
    debug_mode = "--debug-godot" in args

    # Find the script argument and determine the positions of operation and params
    var script_index = args.find("--script")
    if script_index == -1:
        log_error("Could not find --script argument")
        quit(1)

    # The operation should be 2 positions after the script path (script_index + 1 is the script path itself)
    var operation_index = script_index + 2
    # The params should be 3 positions after the script path
    var params_index = script_index + 3

    if args.size() <= params_index:
        log_error("Usage: godot --headless --script godot_operations.gd <operation> <json_params>")
        log_error("Not enough command-line arguments provided.")
        quit(1)

    # Log all arguments for debugging
    log_debug("All arguments: " + str(args))
    log_debug("Script index: " + str(script_index))
    log_debug("Operation index: " + str(operation_index))
    log_debug("Params index: " + str(params_index))

    var operation = args[operation_index]
    var params_json = args[params_index]

    log_info("Operation: " + operation)
    log_debug("Params JSON: " + params_json)

    # Parse JSON using Godot 4.x API
    var json = JSON.new()
    var error = json.parse(params_json)
    var params = null

    if error == OK:
        params = json.get_data()
    else:
        log_error("Failed to parse JSON parameters: " + params_json)
        log_error("JSON Error: " + json.get_error_message() + " at line " + str(json.get_error_line()))
        quit(1)

    if not params:
        log_error("Failed to parse JSON parameters: " + params_json)
        quit(1)

    log_info("Executing operation: " + operation)

    match operation:
        "create_scene":
            create_scene(params)
        "add_node":
            add_node(params)
        "load_sprite":
            load_sprite(params)
        "export_mesh_library":
            export_mesh_library(params)
        "save_scene":
            save_scene(params)
        "get_uid":
            get_uid(params)
        "resave_resources":
            resave_resources(params)
        "read_scene":
            read_scene(params)
        "modify_node":
            modify_node(params)
        "remove_node":
            remove_node(params)
        "attach_script":
            attach_script(params)
        "create_resource":
