# Create a resource file (.tres)
func create_resource(params):
    if not params.has("resource_type") or not params.has("resource_path"):
        printerr("resource_type and resource_path are required")
        quit(1)

    var resource_type = params.resource_type
    var full_resource_path = params.resource_path
    if not full_resource_path.begins_with("res://"):
        full_resource_path = "res://" + full_resource_path

    log_info("Creating resource of type " + resource_type + " at: " + full_resource_path)

    # Instantiate the resource
    if not ClassDB.class_exists(resource_type):
        printerr("Unknown resource type: " + resource_type)
        printerr("Must be a valid Godot class name (e.g., StandardMaterial3D, AudioStreamPlayer, Theme)")
        quit(1)

    if not ClassDB.can_instantiate(resource_type):
        printerr("Cannot instantiate resource type: " + resource_type)
        quit(1)

    var resource = ClassDB.instantiate(resource_type)
    if resource == null:
        printerr("Failed to instantiate resource of type: " + resource_type)
        quit(1)

    if not resource is Resource:
        printerr("Type " + resource_type + " is not a Resource subclass")
        quit(1)

    # Set properties if provided
    if params.has("properties"):
        var properties = params.properties
        for prop_name in properties:
            var raw_value = properties[prop_name]
            var converted_value = _convert_property_value(resource, prop_name, raw_value)
            log_info("Setting " + prop_name + " = " + str(converted_value))
            resource.set(prop_name, converted_value)

    # Ensure directory exists
    var dir_path = full_resource_path.get_base_dir()
    var dir_relative = dir_path.substr(6)  # Remove "res://"
    if not dir_relative.is_empty():
        var dir = DirAccess.open("res://")
        if dir and not dir.dir_exists(dir_relative):
            dir.make_dir_recursive(dir_relative)

    # Save the resource
    var save_error = ResourceSaver.save(resource, full_resource_path)
    if save_error != OK:
        printerr("Failed to save resource: " + str(save_error))
        quit(1)

    print("Resource created successfully at: " + full_resource_path)


func manage_resource(params):
    var resource_path = params.get("resource_path", "")
    var action = params.get("action", "read")
    var full_path = resource_path
    if not full_path.begins_with("res://"):
        full_path = "res://" + full_path

    if action == "read":
        if not ResourceLoader.exists(full_path):
            printerr("Resource not found: " + full_path)
            quit(1)
        var res = ResourceLoader.load(full_path)
        if res == null:
            printerr("Failed to load resource: " + full_path)
            quit(1)
        var props = {}
        for prop in res.get_property_list():
            if prop["usage"] & PROPERTY_USAGE_STORAGE:
                props[prop["name"]] = str(res.get(prop["name"]))
        print("RESOURCE_JSON_START")
        print(JSON.stringify({"type": res.get_class(), "path": full_path, "properties": props}))
        print("RESOURCE_JSON_END")
    elif action == "modify":
        if not ResourceLoader.exists(full_path):
            printerr("Resource not found: " + full_path)
            quit(1)
        var res = ResourceLoader.load(full_path)
        var properties = params.get("properties", {})
        for prop_name in properties:
            var raw_value = properties[prop_name]
            var converted_value = _convert_property_value(res, prop_name, raw_value)
            res.set(prop_name, converted_value)
        ResourceSaver.save(res, full_path)
        print("Resource modified: " + full_path)
    else:
        printerr("Unknown manage_resource action: " + action)
        quit(1)


func manage_scene_signals(params):
    var scene_path = params.get("scene_path", "")
    var action = params.get("action", "list")
    var full_path = scene_path
    if not full_path.begins_with("res://"):
        full_path = "res://" + full_path

    if not FileAccess.file_exists(full_path):
        printerr("Scene not found: " + full_path)
        quit(1)

    var content = FileAccess.get_file_as_string(full_path)

    if action == "list":
        var connections = []
        var lines = content.split("\n")
        for line in lines:
            if line.begins_with("[connection"):
                connections.append(line.strip_edges())
        print("SIGNALS_JSON_START")
        print(JSON.stringify({"connections": connections}))
        print("SIGNALS_JSON_END")
    elif action == "add":
        var signal_name = params.get("signal_name", "")
        var source_path = params.get("source_path", ".")
        var target_path = params.get("target_path", ".")
        var method = params.get("method", "")
        var conn_line = '[connection signal="%s" from="%s" to="%s" method="%s"]' % [signal_name, source_path, target_path, method]
        content += "\n" + conn_line + "\n"
        var file = FileAccess.open(full_path, FileAccess.WRITE)
        file.store_string(content)
        file.close()
        print("Signal connection added: " + conn_line)
    elif action == "remove":
        var signal_name = params.get("signal_name", "")
        var lines = content.split("\n")
        var new_lines = []
        for line in lines:
            if not (line.begins_with("[connection") and signal_name in line):
                new_lines.append(line)
        var file = FileAccess.open(full_path, FileAccess.WRITE)
        file.store_string("\n".join(new_lines))
        file.close()
        print("Signal connections for '%s' removed" % signal_name)
    else:
        printerr("Unknown manage_scene_signals action: " + action)
        quit(1)


func manage_theme_resource(params):
    var resource_path = params.get("resource_path", "")
    var action = params.get("action", "read")
    var full_path = resource_path
    if not full_path.begins_with("res://"):
        full_path = "res://" + full_path

    if action == "create":
        var theme = Theme.new()
        var properties = params.get("properties", {})
        for key in properties:
            theme.set(key, properties[key])
        var dir_path = full_path.get_base_dir()
        var dir_relative = dir_path.substr(6)
        if not dir_relative.is_empty():
            var dir = DirAccess.open("res://")
            if dir and not dir.dir_exists(dir_relative):
                dir.make_dir_recursive(dir_relative)
        ResourceSaver.save(theme, full_path)
        print("Theme created at: " + full_path)
    elif action == "read":
        if not ResourceLoader.exists(full_path):
            printerr("Theme not found: " + full_path)
            quit(1)
        var theme = ResourceLoader.load(full_path)
        print("THEME_JSON_START")
        print(JSON.stringify({"type": theme.get_class(), "path": full_path}))
        print("THEME_JSON_END")
    elif action == "modify":
        if not ResourceLoader.exists(full_path):
            printerr("Theme not found: " + full_path)
            quit(1)
        var theme = ResourceLoader.load(full_path)
        var properties = params.get("properties", {})
        for key in properties:
            theme.set(key, properties[key])
        ResourceSaver.save(theme, full_path)
        print("Theme modified: " + full_path)
    else:
        printerr("Unknown manage_theme_resource action: " + action)
        quit(1)


func manage_scene_structure(params):
    var scene_path = params.get("scene_path", "")
    var action = params.get("action", "rename")
    var node_path_str = params.get("node_path", "")
    var full_path = scene_path
    if not full_path.begins_with("res://"):
        full_path = "res://" + full_path

    if not FileAccess.file_exists(full_path):
        printerr("Scene not found: " + full_path)
        quit(1)
        return

    var scene = load(full_path) as PackedScene
    if scene == null:
        printerr("Failed to load scene: " + full_path)
        quit(1)
        return

    var root = scene.instantiate()
    var target = _resolve_scene_node(root, node_path_str)
    if target == null:
        printerr("Node not found: " + node_path_str)
        quit(1)
        return

    if action == "rename":
        var new_name = params.get("new_name", "")
        if new_name.is_empty():
            printerr("new_name is required for rename")
            quit(1)
            return
        target.name = new_name
        print("Node renamed to '%s'" % target.name)
    elif action == "duplicate":
        if target == root:
            printerr("Cannot duplicate the root node")
            quit(1)
            return
        var dup = target.duplicate()
        target.get_parent().add_child(dup, true)
        _set_owner_recursive(dup, root)
        print("Node duplicated: %s (as '%s')" % [node_path_str, dup.name])
    elif action == "move":
        var new_parent_path = params.get("new_parent_path", "")
        if new_parent_path.is_empty():
            printerr("new_parent_path is required for move")
            quit(1)
            return
        if target == root:
            printerr("Cannot move the root node")
            quit(1)
            return
        var new_parent = _resolve_scene_node(root, new_parent_path)
        if new_parent == null:
            printerr("New parent not found: " + new_parent_path)
            quit(1)
            return
        if new_parent == target or _is_ancestor(target, new_parent):
            printerr("Cannot move a node into itself or one of its descendants")
            quit(1)
            return
        target.get_parent().remove_child(target)
        new_parent.add_child(target, true)
        _set_owner_recursive(target, root)
        print("Node moved: %s -> parent %s (as '%s')" % [node_path_str, new_parent_path, target.name])
    else:
        printerr("Unknown manage_scene_structure action: " + action)
        quit(1)
        return

    var packed = PackedScene.new()
    var pack_result = packed.pack(root)
    if pack_result != OK:
        printerr("Failed to pack scene: " + str(pack_result))
        quit(1)
        return
    var save_error = ResourceSaver.save(packed, full_path)
    if save_error != OK:
        printerr("Failed to save scene: " + str(save_error))
        quit(1)
        return
    print("Scene structure saved: " + full_path)


func _resolve_scene_node(root, tool_path):
    if tool_path == "" or tool_path == "root" or tool_path == ".":
        return root
    var p = tool_path
    if p.begins_with("root/"):
        p = p.substr(5)
    return root.get_node_or_null(p)


func _set_owner_recursive(node, owner_root):
    node.owner = owner_root
    if node.scene_file_path != "":
        return
    for c in node.get_children():
        _set_owner_recursive(c, owner_root)


func _is_ancestor(node, maybe_descendant):
    var n = maybe_descendant.get_parent()
    while n != null:
        if n == node:
            return true
        n = n.get_parent()
    return false


# ===========================================================================
# get_scene_tree
#
# Bounded, depth-first scene tree walk. Depth and total node count share one
# output budget: every emitted real node AND every truncation marker consumes a
# slot. This keeps the returned payload (and therefore the MCP channel) bounded
# regardless of how wide or deep the scene is.
#
# Output contract:
#   - node objects keep only name/type/path/children; visible and process_mode
#     are attached only when the node's OWN stored value is non-default (we do
#     not resolve inherited/effective state, so a hidden ancestor never causes
#     repeated fields down the branch).
#   - depth boundary: a marker is reserved in the parent's children array
#     before descending is cut, so the marker can displace not-yet-visited
#     siblings once the budget is tight.
#   - count exhaustion: the root -> current branch path is always fully
#     materialised first; details live on the parent's "truncated" object
#     (depth/level plus the dropped branch paths), never a top-level boolean.
# ===========================================================================
func get_scene_tree(params):
    print("GET_SCENE_TREE_JSON_START")
    var envelope = _get_scene_tree_build(params)
    print(JSON.stringify(envelope))
    print("GET_SCENE_TREE_JSON_END")

func _get_scene_tree_build(params) -> Dictionary:
    if not params.has("scene_path"):
        return _get_scene_tree_error("INVALID_PARAMS", "scene_path is required")

    var full_scene_path = params.scene_path
    if not full_scene_path.begins_with("res://"):
        full_scene_path = "res://" + full_scene_path

    log_info("get_scene_tree: " + full_scene_path)

    if not FileAccess.file_exists(full_scene_path):
        # Editor has no such/openable scene at this path.
        return _get_scene_tree_error("NO_SCENE", "Scene not found: " + full_scene_path)

    var scene = load(full_scene_path)
    if not scene is PackedScene:
        return _get_scene_tree_error("NO_SCENE", "Failed to load scene: " + full_scene_path)

    var scene_root = scene.instantiate()
    if scene_root == null:
        return _get_scene_tree_error("NO_SCENE", "Failed to instantiate scene: " + full_scene_path)

    # Clamp the shared budget to sane, positive values. Markers count too.
    var max_depth = int(params.get("max_depth", GET_SCENE_TREE_DEFAULT_MAX_DEPTH))
    if max_depth < 1:
        max_depth = 1
    var max_nodes = int(params.get("max_nodes", GET_SCENE_TREE_DEFAULT_MAX_NODES))
    if max_nodes < 1:
        max_nodes = 1

    var state := {
        "budget": max_nodes,
        "used": 0,
        "max_depth": max_depth,
        "truncated": false,
    }

    var root_obj: Dictionary = _get_scene_tree_walk(scene_root, "root", 0, state)

    scene_root.queue_free()

    return {
        "success": true,
        "data": {
            "tree": root_obj,
            "limits": {
                "max_depth": max_depth,
                "max_nodes": max_nodes,
            },
            "used": state["used"],
            "truncated": state["truncated"],
        },
    }

func _get_scene_tree_error(code: String, message: String) -> Dictionary:
    return {
        "success": false,
        "error": {
            "code": code,
            "message": message,
        },
        "data": null,
    }

# Reserve one slot of the shared budget. Returns false once the budget is gone.
func _get_scene_tree_reserve(state: Dictionary) -> bool:
    if state["used"] >= state["budget"]:
        state["truncated"] = true
        return false
    state["used"] += 1
    return true

func _get_scene_tree_marker(reason: String, depth: int, parent_path: String) -> Dictionary:
    return {
        "marker": GET_SCENE_TREE_MARKER,
        "reason": reason,
        "depth": depth,
        "parent_path": parent_path,
    }

# Iterative DFS. Each frame carries the node, its own path, its depth (root = 0),
# the output object already accounting for that node, and the index of the next
# child to inspect. Parent frames stay on the stack so the root -> current path
# is materialised before any sibling subtree is attempted.
func _get_scene_tree_walk(root: Node, root_path: String, root_depth: int, state: Dictionary) -> Dictionary:
    var root_obj := _get_scene_tree_node_info(root, root_path)
    if not _get_scene_tree_reserve(state):
        # Budget cannot even hold the root; report it without children.
        root_obj["truncated"] = _get_scene_tree_truncated(
            root_depth + 1, root_obj["path"], [], "node_limit")
        return root_obj

    var stack: Array = [{
        "node": root,
        "obj": root_obj,
        "path": root_obj["path"],
        "depth": root_depth,
        "next": 0,
    }]

    while stack.size() > 0:
        var frame: Dictionary = stack[stack.size() - 1]
        var node: Node = frame["node"]
        var obj: Dictionary = frame["obj"]
        var depth: int = frame["depth"]
        var children: Array = node.get_children()

        if frame["next"] >= children.size():
            stack.pop_back()
            continue

        var child: Node = children[frame["next"]]
        frame["next"] += 1

        var child_path: String = frame["path"] + "/" + child.name
        var child_depth: int = depth + 1
        var child_arr: Array = obj.get("children", [])
        obj["children"] = child_arr

        # Depth boundary: reserve a marker BEFORE cutting the descent. The
        # marker takes a budget slot and can therefore displace later siblings.
        if child_depth > state["max_depth"]:
            state["truncated"] = true
            if _get_scene_tree_reserve(state):
                child_arr.append(_get_scene_tree_marker("depth_limit", child_depth, frame["path"]))
                _get_scene_tree_note_truncation(
                    obj, child_depth, child_path, "depth_limit")
            else:
                _get_scene_tree_note_truncation(
                    obj, child_depth, child_path, "node_limit")
            continue

        if not _get_scene_tree_reserve(state):
            # Total budget exhausted while this branch is still continuous:
            # record the dropped branch on the parent instead of emitting a
            # partial node.
            state["truncated"] = true
            _get_scene_tree_note_truncation(obj, child_depth, child_path, "node_limit")
            continue

        var child_obj := _get_scene_tree_node_info(child, child_path)
        child_arr.append(child_obj)
        stack.append({
            "node": child,
            "obj": child_obj,
            "path": child_path,
            "depth": child_depth,
            "next": 0,
        })

    return root_obj

# Attach (or merge) a parent-level truncation descriptor. This is the detailed
# replacement for a bare top-level boolean: it names the level/depth and every
# branch that was dropped underneath this node.
func _get_scene_tree_note_truncation(parent_obj: Dictionary, level: int, branch_path: String, reason: String) -> void:
    var truncated: Dictionary = parent_obj.get("truncated", {})
    if truncated.is_empty():
        truncated = _get_scene_tree_truncated(level, parent_obj["path"], [], reason)
        parent_obj["truncated"] = truncated
    truncated["dropped_branches"].append(branch_path)
    if not reason in truncated["reasons"]:
        truncated["reasons"].append(reason)

func _get_scene_tree_truncated(level: int, parent_path: String, dropped_branches: Array, reason: String) -> Dictionary:
    return {
        "depth": level,
        "level": level,
        "at": parent_path,
        "reasons": [reason],
        "dropped_branches": dropped_branches,
    }

func _get_scene_tree_node_info(node: Node, node_path: String) -> Dictionary:
    var info := {
        "name": str(node.name),
        "type": node.get_class(),
        "path": node_path,
        "children": [],
    }

    # Own stored visibility only: Node.visible defaults to true. We never read
    # is_visible_in_tree(), so an invisible ancestor does not repeat the field
    # on every descendant.
    if not node.visible:
        info["visible"] = false

    # Own stored process mode only: PROCESS_MODE_INHERIT (0) is the default and
    # means "derive from parent", so it is omitted rather than expanded.
    var own_process_mode: int = node.process_mode
    if own_process_mode != Node.PROCESS_MODE_INHERIT:
        info["process_mode"] = own_process_mode

    return info

