import { expect, it } from 'vitest';
import { mkdtempSync, rmSync, symlinkSync, unlinkSync } from 'fs';
import { tmpdir } from 'os';
import { dirname, join } from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import { execFile } from 'child_process';
import { promisify } from 'util';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';

it('initializes the stdio server when its executable is reached through a directory alias', async () => {
  const directory = mkdtempSync(join(tmpdir(), 'godot-cli-entry-'));
  const alias = join(directory, 'entry');
  const build = join(dirname(fileURLToPath(import.meta.url)), '..', 'build');
  symlinkSync(build, alias, process.platform === 'win32' ? 'junction' : 'dir');
  const transport = new StdioClientTransport({
    command: process.execPath,
    args: [join(alias, 'index.js')],
    env: { GODOT_PATH: process.execPath },
    stderr: 'pipe'
  });
  const client = new Client({ name: 'cli-entry-regression', version: '1.0.0' });
  try {
    await client.connect(transport);
    const { tools } = await client.listTools();
    expect(tools).toHaveLength(157);
    expect(tools.some(tool => tool.name === 'read_file')).toBe(true);
  } finally {
    await client.close();
    unlinkSync(alias);
    rmSync(directory, { recursive: true, force: true });
  }
}, 15000);

it('keeps library imports safe when the entry argument is absent or unresolvable', async () => {
  const entry = pathToFileURL(join(dirname(fileURLToPath(import.meta.url)), '..', 'build', 'index.js')).href;
  const execute = promisify(execFile);
  for (const argument of [undefined, join(tmpdir(), 'godot-mcp-missing-entry.js')]) {
    const assign = argument === undefined ? 'delete process.argv[1]' : 'process.argv[1] = ' + JSON.stringify(argument);
    const code = assign + '; await import(' + JSON.stringify(entry) + '); process.stdout.write("imported");';
    const { stdout } = await execute(process.execPath, ['--input-type=module', '-e', code], { timeout: 5000 });
    expect(stdout).toBe('imported');
  }
}, 15000);

import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { appendBoundedLines, readLogPage } from '../src/logs.js';
import { isPathWithinAllowedRoots, validateToolPaths } from '../src/security.js';

describe('MCP filesystem boundaries', () => {
  const workspace = mkdtempSync(join(tmpdir(), 'godot-mcp-test-'));
  const allowed = join(workspace, 'allowed');
  const outside = join(workspace, 'allowed-sibling');
  const project = join(allowed, 'project');
  const client = new Client({ name: 'regression-tests', version: '1.0.0' });
  let instance: any;
  let addedListeners: NodeJS.SignalsListener[];

  beforeAll(async () => {
    mkdirSync(project, { recursive: true });
    mkdirSync(outside, { recursive: true });
    for (const directory of [project, outside]) {
      writeFileSync(join(directory, 'project.godot'), 'config_version=5\n');
      writeFileSync(join(directory, 'secret.txt'), 'original');
    }
    symlinkSync(outside, join(project, 'escape'), process.platform === 'win32' ? 'junction' : 'dir');
    vi.stubEnv('GODOT_MCP_ALLOWED_DIRS', allowed);
    const { GodotServer } = await import('../src/index.js');
    const listeners = process.listeners('SIGINT');
    instance = new GodotServer();
    addedListeners = process.listeners('SIGINT').filter(listener => !listeners.includes(listener));
    const [serverTransport, clientTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([instance.server.connect(serverTransport), client.connect(clientTransport)]);
  });

  afterAll(async () => {
    await client.close();
    await instance?.server.close();
    for (const listener of addedListeners || []) process.removeListener('SIGINT', listener);
    vi.unstubAllEnvs();
    rmSync(workspace, { recursive: true, force: true });
  });

  it.each(['read_file', 'write_file', 'delete_file', 'create_directory', 'launch_editor', 'create_project', 'read_scene', 'create_scene', 'manage_plugins', 'set_main_scene'])('rejects an outside project for %s before side effects', async name => {
    const result = await client.callTool({ name, arguments: { project_path: outside, filePath: 'secret.txt', content: 'changed', directoryPath: 'new', scenePath: 'main.tscn', projectName: 'test', action: 'list' } });
    expect(result.isError).toBe(true);
    expect(JSON.stringify(result.content)).toContain('outside the allowed roots');
    expect(readFileSync(join(outside, 'secret.txt'), 'utf8')).toBe('original');
  });

  it('allows valid file reads within the project', async () => {
    const result = await client.callTool({ name: 'read_file', arguments: { projectPath: project, filePath: 'secret.txt' } });
    expect(result.isError).not.toBe(true);
    expect(JSON.stringify(result.content)).toContain('original');
  });

  it('rejects symbolic-link escape including new files under it', async () => {
    for (const filePath of ['escape/secret.txt', 'escape/new/nested.txt']) {
      const result = await client.callTool({ name: 'write_file', arguments: { projectPath: project, filePath, content: 'changed' } });
      expect(result.isError).toBe(true);
      expect(JSON.stringify(result.content)).toContain('outside the project directory');
    }
    expect(readFileSync(join(outside, 'secret.txt'), 'utf8')).toBe('original');
  });

  it('rejects traversal and outside discovery/export roots', async () => {
    expect(validateToolPaths({ projectPath: project, filePath: '../secret.txt' }, [allowed])).toContain('outside the project');
    expect(validateToolPaths({ projectPath: project, outputPath: outside }, [allowed])).toContain('outside the allowed roots');
    expect(isPathWithinAllowedRoots(outside, [allowed])).toBe(false);
    const result = await client.callTool({ name: 'list_projects', arguments: { directory: outside } });
    expect(result.isError).toBe(true);
  });

  it('checks normalized path aliases and script path arrays', async () => {
    const requests = [
      { name: 'write_file', arguments: { project_path: project, file_path: 'escape/secret.txt', content: 'changed' } },
      { name: 'validate_scripts', arguments: { project_path: project, script_paths: [join(outside, 'script.gd')] } },
      { name: 'export_project', arguments: { project_path: project, output_path: join(outside, 'export.exe'), preset_name: 'Windows' } }
    ];
    for (const request of requests) {
      const result = await client.callTool(request);
      expect(result.isError).toBe(true);
      expect(JSON.stringify(result.content)).toContain('outside');
    }
    expect(readFileSync(join(outside, 'secret.txt'), 'utf8')).toBe('original');
  });

  it('provides items for every array in every advertised schema', async () => {
    const { tools } = await client.listTools();
    expect(tools).toHaveLength(157);
    function visit(schema: any) {
      if (!schema || typeof schema !== 'object') return;
      if (schema.type === 'array') expect(schema.items).toBeDefined();
      for (const value of Object.values(schema)) visit(value);
    }
    for (const tool of tools) visit(tool.inputSchema);
  });

  it('propagates the detected engine version to new project feature flags', async () => {
    const version = vi.spyOn(instance, 'detectGodotNetSdkVersion').mockResolvedValue('4.7.0');
    const destination = join(allowed, 'scaffold');
    const result = await client.callTool({ name: 'create_project', arguments: { projectPath: destination, projectName: 'Scaffold', dotnet: true } });
    expect(result.isError).not.toBe(true);
    expect(readFileSync(join(destination, 'project.godot'), 'utf8')).toContain('PackedStringArray("4.7", "C#")');
    expect(readFileSync(join(destination, 'Scaffold.csproj'), 'utf8')).toContain('Godot.NET.Sdk/4.7.0');
    version.mockRestore();
  });

  it('returns independent cursor pages through the actual log handler', async () => {
    instance.activeProcess = { output: ['one', 'two', 'three'], errors: [], outputOffset: 10, errorOffset: 0, process: { kill: () => {} } };
    const first: any = await client.callTool({ name: 'game_get_logs', arguments: { cursor: 0, limit: 2 } });
    const firstPage = JSON.parse(first.content[0].text);
    expect(firstPage).toMatchObject({ logs: ['one', 'two'], nextCursor: 12, dropped: true, hasMore: true });
    const second: any = await client.callTool({ name: 'game_get_logs', arguments: { cursor: firstPage.nextCursor, limit: 2 } });
    expect(JSON.parse(second.content[0].text)).toMatchObject({ logs: ['three'], nextCursor: 13, hasMore: false });
    instance.activeProcess = null;
  });
});

describe('bounded runtime logs', () => {
  it('retains the newest lines and bounds individual line size', () => {
    const buffer = ['old'];
    expect(appendBoundedLines(buffer, ['x'.repeat(10000), 'latest'], 2)).toBe(1);
    expect(buffer[0]).toHaveLength(4096);
    expect(buffer[1]).toBe('latest');
  });

  it('rejects invalid cursors and page sizes', () => {
    expect(() => readLogPage([], 0, -1)).toThrow('cursor');
    expect(() => readLogPage([], 0, 0, 501)).toThrow('limit');
  });
});

/**
 * Handler tests for Godot MCP server.
 *
 * Because GodotServer is not exported and auto-starts on import, we cannot
 * instantiate it directly.  Instead we test the handler logic by:
 *   1. Importing the source as raw text and verifying structural invariants.
 *   2. Testing the pure utility helpers that handlers depend on (normalizeParameters,
 *      validatePath, convertCamelToSnakeCase, createErrorResponse).
 *   3. Exercising the gameCommand / headlessOp patterns via focused unit-style
 *      tests that simulate what each handler does with its arguments.
 */

import { describe, it, expect, beforeAll } from 'vitest';
import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import {
  normalizeParameters,
  convertCamelToSnakeCase,
  validatePath,
  createErrorResponse,
} from '../src/utils.js';

const __dirname = dirname(fileURLToPath(import.meta.url));

let sourceCode: string;

beforeAll(() => {
  sourceCode = readFileSync(join(__dirname, '..', 'src', 'index.ts'), 'utf8');
});

// ---------------------------------------------------------------------------
// Helpers that replicate the core logic of gameCommand / headlessOp so we can
// unit-test argument validation and transform functions extracted from handlers.
// ---------------------------------------------------------------------------

function fakeGameCommand(
  hasActiveProcess: boolean,
  hasConnection: boolean,
  args: any,
  argsFn: (a: any) => Record<string, any>,
): { error: string | null; commandArgs: Record<string, any> | null } {
  if (!hasActiveProcess) return { error: 'No active Godot process. Use run_project first.', commandArgs: null };
  if (!hasConnection) return { error: 'Not connected to game interaction server.', commandArgs: null };
  args = normalizeParameters(args || {});
  try {
    return { error: null, commandArgs: argsFn(args) };
  } catch (e: any) {
    return { error: e.message, commandArgs: null };
  }
}

function fakeHeadlessOp(
  args: any,
  argsFn: (a: any) => { projectPath: string; params: any },
  projectExists: boolean = true,
): { error: string | null; operation: { projectPath: string; params: any } | null } {
  args = normalizeParameters(args || {});
  const { projectPath, params } = argsFn(args);
  if (!projectPath) return { error: 'projectPath is required.', commandArgs: null } as any;
  if (!validatePath(projectPath)) return { error: 'Invalid path.', commandArgs: null } as any;
  if (!projectExists) return { error: `Not a valid Godot project: ${projectPath}`, commandArgs: null } as any;
  return { error: null, operation: { projectPath, params } };
}

// ---------------------------------------------------------------------------
// 1. gameCommand-based handler tests
// ---------------------------------------------------------------------------
describe('Game command handlers — argument transforms', () => {
  // game_click
  describe('handleGameClick', () => {
    const argsFn = (a: any) => ({ x: a.x ?? 0, y: a.y ?? 0, button: a.button ?? 1 });

    it('defaults x/y to 0 and button to 1', () => {
      const r = fakeGameCommand(true, true, {}, argsFn);
      expect(r.error).toBeNull();
      expect(r.commandArgs).toEqual({ x: 0, y: 0, button: 1 });
    });

    it('passes provided coordinates', () => {
      const r = fakeGameCommand(true, true, { x: 100, y: 200, button: 2 }, argsFn);
      expect(r.commandArgs).toEqual({ x: 100, y: 200, button: 2 });
    });

    it('returns error when no active process', () => {
      const r = fakeGameCommand(false, true, {}, argsFn);
      expect(r.error).toContain('No active Godot process');
    });

    it('returns error when not connected', () => {
      const r = fakeGameCommand(true, false, {}, argsFn);
      expect(r.error).toContain('Not connected');
    });
  });

  // game_mouse_move
  describe('handleGameMouseMove', () => {
    const argsFn = (a: any) => ({
      x: a.x ?? 0, y: a.y ?? 0, relative_x: a.relative_x ?? 0, relative_y: a.relative_y ?? 0,
    });

    it('defaults all values to 0', () => {
      const r = fakeGameCommand(true, true, {}, argsFn);
      expect(r.commandArgs).toEqual({ x: 0, y: 0, relative_x: 0, relative_y: 0 });
    });

    it('preserves provided values', () => {
      const r = fakeGameCommand(true, true, { x: 10, y: 20, relative_x: 5, relative_y: -3 }, argsFn);
      expect(r.commandArgs).toEqual({ x: 10, y: 20, relative_x: 5, relative_y: -3 });
    });
  });

  // game_get_ui (no args)
  describe('handleGameGetUi', () => {
    it('sends empty args', () => {
      const r = fakeGameCommand(true, true, {}, () => ({}));
      expect(r.commandArgs).toEqual({});
    });
  });

  // game_get_scene_tree (no args)
  describe('handleGameGetSceneTree', () => {
    it('sends empty args', () => {
      const r = fakeGameCommand(true, true, {}, () => ({}));
      expect(r.commandArgs).toEqual({});
    });
  });

  // game_eval
  describe('handleGameEval', () => {
    it('passes code parameter', () => {
      const args = normalizeParameters({ code: 'get_tree().root.name' });
      const r = fakeGameCommand(true, true, args, a => ({ code: a.code }));
      expect(r.commandArgs).toEqual({ code: 'get_tree().root.name' });
    });
  });

  // game_get_property
  describe('handleGameGetProperty', () => {
    const argsFn = (a: any) => ({ node_path: a.nodePath, property: a.property });

    it('maps nodePath to node_path', () => {
      const args = normalizeParameters({ node_path: '/root/Player', property: 'position' });
      const r = fakeGameCommand(true, true, args, argsFn);
      expect(r.commandArgs).toEqual({ node_path: '/root/Player', property: 'position' });
    });

    it('accepts already camelCase nodePath', () => {
      const r = fakeGameCommand(true, true, { nodePath: '/root/Enemy', property: 'health' }, argsFn);
      expect(r.commandArgs).toEqual({ node_path: '/root/Enemy', property: 'health' });
    });
  });

  // game_set_property
  describe('handleGameSetProperty', () => {
    const argsFn = (a: any) => ({
      node_path: a.nodePath, property: a.property, value: a.value, type_hint: a.typeHint || '',
    });

    it('maps all params correctly', () => {
      const r = fakeGameCommand(true, true, {
        nodePath: '/root/Player', property: 'speed', value: 100, typeHint: 'int',
      }, argsFn);
      expect(r.commandArgs).toEqual({
        node_path: '/root/Player', property: 'speed', value: 100, type_hint: 'int',
      });
    });

    it('defaults type_hint to empty string', () => {
      const r = fakeGameCommand(true, true, {
        nodePath: '/root/P', property: 'x', value: 0,
      }, argsFn);
      expect(r.commandArgs!.type_hint).toBe('');
    });
  });

  // game_call_method
  describe('handleGameCallMethod', () => {
    const argsFn = (a: any) => ({
      node_path: a.nodePath, method: a.method, args: a.args || [],
    });

    it('sends method with empty args array by default', () => {
      const r = fakeGameCommand(true, true, { nodePath: '/root/P', method: 'jump' }, argsFn);
      expect(r.commandArgs).toEqual({ node_path: '/root/P', method: 'jump', args: [] });
    });

    it('passes provided args array', () => {
      const r = fakeGameCommand(true, true, {
        nodePath: '/root/P', method: 'take_damage', args: [10, 'fire'],
      }, argsFn);
      expect(r.commandArgs!.args).toEqual([10, 'fire']);
    });
  });

  // game_get_node_info
  describe('handleGameGetNodeInfo', () => {
    it('passes nodePath as node_path', () => {
      const r = fakeGameCommand(true, true, { nodePath: '/root/UI' }, a => ({ node_path: a.nodePath }));
      expect(r.commandArgs).toEqual({ node_path: '/root/UI' });
    });
  });

  // game_instantiate_scene
  describe('handleGameInstantiateScene', () => {
    const argsFn = (a: any) => ({
      scene_path: a.scenePath, parent_path: a.parentPath || '/root',
    });

    it('defaults parent_path to /root', () => {
      const r = fakeGameCommand(true, true, { scenePath: 'res://enemy.tscn' }, argsFn);
      expect(r.commandArgs).toEqual({ scene_path: 'res://enemy.tscn', parent_path: '/root' });
    });

    it('accepts custom parent_path', () => {
      const r = fakeGameCommand(true, true, {
        scenePath: 'res://bullet.tscn', parentPath: '/root/Bullets',
      }, argsFn);
