  // game_mouse_drag
  describe('handleGameMouseDrag', () => {
    const argsFn = (a: any) => ({
      from_x: a.fromX, from_y: a.fromY, to_x: a.toX, to_y: a.toY,
      button: a.button || 1, steps: a.steps || 10,
    });

    it('maps all drag params', () => {
      const r = fakeGameCommand(true, true, {
