      expect(r.commandArgs).toEqual({ code: 'get_tree().root.name' });
    });
  });

  // game_get_property
  describe('handleGameGetProperty', () => {
    const argsFn = (a: any) => ({ node_path: a.nodePath, property: a.property });

    it('maps nodePath to node_path', () => {
