  // game_pause
  describe('handleGamePause', () => {
    const argsFn = (a: any) => ({ paused: a.paused !== undefined ? a.paused : true });

    it('defaults paused to true', () => {
      const r = fakeGameCommand(true, true, {}, argsFn);
      expect(r.commandArgs).toEqual({ paused: true });
